fn='''function clearStoryUI(){prologue=null;commsFinish=null;$('#commsLayer')?.remove();$('#tutorialGoal')?.remove();$('#tutorialExit')?.remove();}
function startPrologue(replay=false){clearStoryUI();if(replay){record.skipStory=false;saveRecord();}launch(0,'pistol',[],false,0,null);run.tutorial=true;run.entities=[];run.effects=[];run.joins=[];run.enemyBullets=[];run.bullets=[];run.inventory=[];run.army=4;run.syncMembers();run.nextWave=Infinity;run.shotClock=Infinity;run.time=0;run.drain();hudSignature='';prologue=new EmberStory.Prologue();const exit=document.createElement('button');exit.id='tutorialExit';exit.textContent='跳过序章';exit.onclick=()=>finishPrologue(true);$('#frame').append(exit);showComms('opening',()=>tutorialPhase('move'));}
function showComms(script,onDone){clearAim();if(record.skipStory){onDone();return;}prologue.phase='dialog';prologue.dialogue=EmberStory.SCRIPTS[script];prologue.line=0;run.pause();mixer.setMode('paused');$('#hud').hidden=true;$('#tutorialGoal')?.remove();$('#tutorialExit').hidden=true;commsFinish=onDone;$('#commsLayer')?.remove();const layer=document.createElement('section');layer.id='commsLayer';layer.innerHTML='<div class="comms-top"><span>FIELD COMMUNICATIONS</span><b id="commsChannel"></b></div><button id="skipStory">跳过全部剧情 ›</button><div id="commsPortrait" class="comms-portrait"></div><div class="unknown-wave" id="unknownWave"><span>？</span><svg viewBox="0 0 260 70"><path d="M0 35H25L35 20L45 51L55 9L65 59L75 28L85 40L95 22L105 49L115 17L125 57L135 30L145 40L155 15L165 55L175 25L185 45L195 20L205 50L215 30L225 35H260"/></svg><small>UNIDENTIFIED SIGNAL</small></div><div class="comms-card"><div class="comms-speaker"><b id="commsName"></b><small id="commsRole"></small></div><button id="commsNext" aria-label="继续对话"><span id="commsText"></span><i>继续 ▸</i></button><div class="comms-bottom"><span id="commsCount"></span><small>通讯记录 / 指挥部频道</small></div></div>';$('#frame').append(layer);$('#commsNext').onclick=commsNext;$('#skipStory').onclick=()=>{record.skipStory=true;saveRecord();mixer.ui('cancel');closeComms();};setCommsLine();}
function setCommsLine(){if(!prologue)return;const [speaker,text]=prologue.dialogue[prologue.line],cast=EmberStory.CAST[speaker];prologue.revealed=false;commsStart=visualTime;$('#commsLayer').dataset.speaker=speaker;$('#commsName').textContent=cast.name;$('#commsRole').textContent=cast.role;$('#commsChannel').textContent=speaker==='unknown'?'?? / SIGNAL LOST':'CH. 07 / LINK STABLE';$('#commsPortrait').className='comms-portrait '+(cast.portrait===1?'commander':'liaison');$('#commsPortrait').hidden=cast.portrait===null;$('#unknownWave').hidden=speaker!=='unknown';$('#commsText').textContent='';$('#commsCount').textContent=`${String(prologue.line+1).padStart(2,'0')} / ${String(prologue.dialogue.length).padStart(2,'0')}`;mixer.play('radio-static',speaker==='unknown'?.38:.1);if(speaker==='unknown'&&prologue.line===0)mixer.speak('unknown');if(speaker==='liaison'&&text.includes('信号接通'))mixer.speak('linked');}
function commsNext(){if(!prologue||prologue.phase!=='dialog')return;const text=prologue.dialogue[prologue.line][1];if(!prologue.revealed){prologue.revealed=true;$('#commsText').textContent=text;return;}mixer.ui('input');prologue.line++;if(prologue.line>=prologue.dialogue.length){closeComms();return;}setCommsLine();}
function closeComms(){mixer.stopSpeech();$('#commsLayer')?.remove();const done=commsFinish;commsFinish=null;if(done)done();}
function tutorialPhase(phase){if(!prologue)return;prologue.setPhase(phase,run);run.resume();run.entities=[];run.effects=[];run.bullets=[];run.enemyBullets=[];run.nextWave=Infinity;$('#hud').hidden=false;$('#tutorialExit').hidden=false;const goals={move:['向右移动','左右拖动屏幕，靠近右侧求救信号'],rescue:['解救幸存者','对准围困者，队伍会自动向前射击'],airstrike:['申请空中支援','点左侧支援，按图案一笔连线'],orbital:['申请轨道激光','绘制激光指令，再选择重装目标附近落点']};if(phase==='move'){run.inventory=[];run.shotClock=Infinity;}if(phase==='rescue'){run.spawnRescue(1,300,4,100);run.shotClock=0;}if(phase==='airstrike'){run.inventory=[{type:'bomb',count:1}];run.spawnHorde(0,310,12,0);for(const o of run.entities){o.hp=o.max=200;o.speed=0;}run.shotClock=0;}if(phase==='orbital'){run.inventory=[{type:'laser',count:1}];run.heavySpent=[];run.unit('armored',216,310,{hp:8000,max:8000,armor:0,speed:0});run.shotClock=0;}$('#tutorialGoal')?.remove();const goal=document.createElement('div');goal.id='tutorialGoal';goal.innerHTML=`<small>序章 · ${({move:'01',rescue:'02',airstrike:'03',orbital:'04'})[phase]} / 04</small><b>${goals[phase][0]}</b><span>${goals[phase][1]}</span>`;$('#frame').append(goal);hudSignature='';hud();}
function updatePrologue(){if(!prologue)return;if(prologue.phase==='dialog'){if(!prologue.revealed){const text=prologue.dialogue[prologue.line][1],count=Math.floor((visualTime-commsStart)*28);$('#commsText').textContent=text.slice(0,count);if(count>=text.length)prologue.revealed=true;}return;}if(run?.state!=='playing')return;for(const o of run.entities)if(o.type==='rescue')o.y=Math.min(o.y,410);if(aim&&$('#tutorialGoal'))$('#tutorialGoal span').textContent='拖到敌人所在位置，松手投放；此时才进入慢动作';const next=prologue.observe(run);if(next==='rescue')showComms('rescue',()=>tutorialPhase('rescue'));if(next==='airstrike')showComms('airstrike',()=>tutorialPhase('airstrike'));if(next==='orbital')showComms('orbital',()=>tutorialPhase('orbital'));if(next==='ending')showComms('ending',()=>finishPrologue(false));if(['airstrike','orbital'].includes(prologue?.phase)&&prologue.cast&&!run.effects.some(e=>e.type===prologue.cast)&&!run.inventory.some(i=>i?.type===prologue.cast)&&run.time-prologue.phaseStarted>5){const type=prologue.phase==='airstrike'?'bomb':'laser';run.inventory=[{type,count:1}];run.heavySpent=[];prologue.cast=null;prologue.phaseStarted=run.time;hudSignature='';toast('联络员：重新标记落点，我会再次调度支援。',2);}}
function finishPrologue(skipped=false){record.prologueCompleted=true;saveRecord();clearAim();clearStoryUI();mixer.stopSpeech();run=null;screen='prologueComplete';overlayState='prologueComplete';$('#overlay').dataset.view=overlayState;$('#hud').hidden=true;$('#overlay').innerHTML=`<small class="clear-label">序章 / 断线重连</small><h2 class="panel-title">${skipped?'通讯待命':'通讯已建立'}</h2><div class="prologue-seal">07</div><p class="prologue-end-copy">联络员林澈与你保持联系。<br>第一段撤离路线已上传。</p><button class="primary" id="prologueDeploy">进入第一章</button><button class="secondary" id="prologueHome">返回首页</button>`;$('#prologueDeploy').onclick=()=>start(0,false,0);$('#prologueHome').onclick=menu;}
'''
